///$tab Main
SET ThousandSep=' ';
SET DecimalSep=',';
SET MoneyThousandSep=' ';
SET MoneyDecimalSep='.';
SET MoneyFormat='# ##0.00 CHF;-# ##0.00 CHF';
SET TimeFormat='hh:mm:ss';
SET DateFormat='DD.MM.YYYY';
SET TimestampFormat='DD.MM.YYYY hh:mm:ss[.fff]';
SET FirstWeekDay=0;
SET BrokenWeeks=0;
SET ReferenceDay=4;
SET FirstMonthOfYear=1;
SET CollationLocale='fr-CH';
SET CreateSearchIndexOnReload=1;
SET MonthNames='janv.;févr.;mars;avr.;mai;juin;juil.;août;sept.;oct.;nov.;déc.';
SET LongMonthNames='janvier;février;mars;avril;mai;juin;juillet;août;septembre;octobre;novembre;décembre';
SET DayNames='lun.;mar.;mer.;jeu.;ven.;sam.;dim.';
SET LongDayNames='lundi;mardi;mercredi;jeudi;vendredi;samedi;dimanche';
SET NumericalAbbreviation='3:k;6:M;9:G;12:T;15:P;18:E;21:Z;24:Y;-3:m;-6:μ;-9:n;-12:p;-15:f;-18:a;-21:z;-24:y';

///$tab Section 3
// ============================================================
// QLIK SENSE - INVESTMENT TRACKING - LOAD SCRIPT
// Built from: datas_demo_edr dataset (actual column names)
// ============================================================

// ── GLOBAL VARIABLES ─────────────────────────────────────────
SET ThousandSep=' ';
SET DecimalSep=',';
SET MoneyThousandSep=' ';
SET MoneyDecimalSep=',';
SET MoneyFormat='# ##0,00 EUR;-# ##0,00 EUR';
SET TimeFormat='hh:mm:ss';
SET DateFormat='YYYY-MM-DD';
SET TimestampFormat='YYYY-MM-DD hh:mm:ss[.fff]';
SET FirstWeekDay=0;
SET BrokenWeeks=1;
SET ReferenceDay=4;
SET FirstMonthOfYear=1;
SET CollationLocale='fr-FR';
SET CreateSearchIndexOnReload=1;

LET vDataPath = 'lib://InvestmentData/';

// ============================================================
// SECTION 1 : DIMENSION TABLES
// ============================================================

// ── DIM_CALENDRIER ───────────────────────────────────────────
// CSV columns: Date,Annee,Trimestre,Mois,NomMois,Semaine,
//              JourSemaine,NomJour,EstWeekend,EstJourFerie,
//              Semestre,AnneeMois,AnneeTrimestreTxt
[Dim_Calendrier]:
LOAD
    Date#(Date, 'YYYY-MM-DD')      AS [Date],
    Num#(Annee)                    AS [Annee],
    Num#(Trimestre)                AS [Trimestre],
    Num#(Mois)                     AS [Mois],
    NomMois                        AS [Nom Mois],
    Num#(Semaine)                  AS [Semaine],
    Num#(JourSemaine)              AS [Jour Semaine],
    NomJour                        AS [Nom Jour],
    Num#(EstWeekend)               AS [Est Weekend],
    Num#(EstJourFerie)             AS [Est Jour Ferie],
    Num#(Semestre)                 AS [Semestre],
    AnneeMois                      AS [Annee-Mois],
    AnneeTrimestreTxt              AS [Annee-Trimestre],
    If(Num#(EstWeekend)=0, 'Jour Ouvre', 'Weekend') AS [Type Jour]
FROM [$(vDataPath)dim_calendrier.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── DIM_CLIENTS ──────────────────────────────────────────────
// CSV columns: ClientID,Nom,Prenom,Email,Telephone,DateNaissance,
//              Segment,Pays,Ville,DateEntreeRelation,Conseiller,
//              ProfilRisque,StatutKYC
// Note: join key to Dim_Conseillers is [Conseiller] = ConseillerID
[Dim_Clients]:
LOAD
    ClientID,
    Nom                                      AS [Nom Client],
    Prenom                                   AS [Prenom Client],
    Nom & ' ' & Prenom                       AS [Nom Complet Client],
    Email                                    AS [Email Client],
    Telephone,
    Date#(DateNaissance, 'YYYY-MM-DD')       AS [Date Naissance],
    Year(Today()) - Year(Date#(DateNaissance, 'YYYY-MM-DD')) AS [Age Client],
    Segment                                  AS [Segment Client],
    Pays                                     AS [Pays Client],
    Ville                                    AS [Ville Client],
    Date#(DateEntreeRelation, 'YYYY-MM-DD')  AS [Date Entree Relation],
    Year(Today()) - Year(Date#(DateEntreeRelation, 'YYYY-MM-DD')) AS [Anciennete (ans)],
    Conseiller                               AS ConseillerID,
    ProfilRisque                             AS [Profil Risque],
    StatutKYC                                AS [Statut KYC]
FROM [$(vDataPath)dim_clients.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── DIM_CONSEILLERS ──────────────────────────────────────────
// CSV columns: ConseillerID,Nom,Prenom,Email,Bureau,Equipe,
//              AnneeExperience,Certification,NbClients,AuM_EUR
[Dim_Conseillers]:
LOAD
    ConseillerID,
    Nom                            AS [Nom Conseiller],
    Prenom                         AS [Prenom Conseiller],
    Nom & ' ' & Prenom             AS [Nom Complet Conseiller],
    Email                          AS [Email Conseiller],
    Bureau,
    Equipe,
    Num#(AnneeExperience)          AS [Annees Experience],
    Certification,
    Num#(NbClients)                AS [Nb Clients Conseiller],
    Num#(AuM_EUR)                  AS [AuM Conseiller (EUR)]
FROM [$(vDataPath)dim_conseillers.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── DIM_INSTRUMENTS ──────────────────────────────────────────
// CSV columns: InstrumentID,NomInstrument,TypeInstrument,Classe Actif,
//              Devise,Pays,ISIN,Emetteur,NiveauRisque,FraisGestion_pct
// Note: column is literally "Classe Actif" (with space, no apostrophe)
[Dim_Instruments]:
LOAD
    InstrumentID,
    NomInstrument                  AS [Nom Instrument],
    TypeInstrument                 AS [Type Instrument],
    [Classe Actif]                 AS [Classe Actif],
    Devise                         AS [Devise Instrument],
    Pays                           AS [Pays Instrument],
    ISIN,
    Emetteur,
    NiveauRisque                   AS [Niveau Risque],
    Num#(FraisGestion_pct)         AS [Frais Gestion (%)]
FROM [$(vDataPath)dim_instruments.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── DIM_PORTEFEUILLES ────────────────────────────────────────
// CSV columns: PortefeuilleID,ClientID,TypePortefeuille,DateOuverture,
//              Devise,Statut,ObjectifInvestissement,HorizonInvestissement,
//              BenchmarkRef
[Dim_Portefeuilles]:
LOAD
    PortefeuilleID,
    ClientID,
    TypePortefeuille               AS [Type Portefeuille],
    Date#(DateOuverture, 'YYYY-MM-DD') AS [Date Ouverture],
    Devise                         AS [Devise Portefeuille],
    Statut                         AS [Statut Portefeuille],
    ObjectifInvestissement         AS [Objectif Investissement],
    HorizonInvestissement          AS [Horizon Investissement],
    BenchmarkRef                   AS [Benchmark Reference]
FROM [$(vDataPath)dim_portefeuilles.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ============================================================
// SECTION 2 : FACT TABLES
// ============================================================

// ── FACT_TRANSACTIONS ────────────────────────────────────────
// CSV columns: TransactionID,PortefeuilleID,InstrumentID,DateTransaction,
//              TypeTransaction,Quantite,PrixUnitaire,MontantBrut,Frais,
//              MontantNet,Devise,TauxChange_EUR,MontantNet_EUR,Statut,
//              Courtier,Operateur
// Statut values in data: 'Exécuté', 'En attente', 'Annulé'
// TypeTransaction values: Achat, Vente, Dividende, Coupon, Frais,
//                         Arbitrage Entrant, Arbitrage Sortant
[Fact_Transactions]:
LOAD
    TransactionID,
    PortefeuilleID,
    InstrumentID,
    Date#(DateTransaction, 'YYYY-MM-DD')  AS [Date Transaction],
    Date#(DateTransaction, 'YYYY-MM-DD')  AS [Date],
    TypeTransaction                        AS [Type Transaction],
    Num#(Quantite)                         AS [Quantite],
    Num#(PrixUnitaire)                     AS [Prix Unitaire (EUR)],
    Num#(MontantBrut)                      AS [Montant Brut (EUR)],
    Num#(Frais)                            AS [Frais (EUR)],
    Num#(MontantNet)                       AS [Montant Net],
    Devise                                 AS [Devise Transaction],
    Num#(TauxChange_EUR)                   AS [Taux Change EUR],
    Num#(MontantNet_EUR)                   AS [Montant Net EUR],
    Statut                                 AS [Statut Transaction],
    Courtier,
    Operateur,
    // Pre-split amounts by transaction type
    If(TypeTransaction='Achat',             Num#(MontantNet_EUR), 0) AS [Montant Achat EUR],
    If(TypeTransaction='Vente',             Num#(MontantNet_EUR), 0) AS [Montant Vente EUR],
    If(TypeTransaction='Dividende' Or TypeTransaction='Coupon',
                                            Num#(MontantNet_EUR), 0) AS [Revenus EUR],
    If(TypeTransaction='Frais',             Num#(MontantNet_EUR), 0) AS [Total Frais EUR],
    If(TypeTransaction='Arbitrage Entrant', Num#(MontantNet_EUR), 0) AS [Arbitrage Entrant EUR],
    If(TypeTransaction='Arbitrage Sortant', Num#(MontantNet_EUR), 0) AS [Arbitrage Sortant EUR]
FROM [$(vDataPath)fact_transactions.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq)
WHERE Statut = 'Exécuté';


// ── FACT_POSITIONS ───────────────────────────────────────────
// CSV columns: SnapshotDate,PortefeuilleID,InstrumentID,Quantite,
//              PrixRevientUnitaire,PrixMarcheUnitaire,ValeurAchat_EUR,
//              ValeurMarche_EUR,PnL_EUR,PnL_pct,PoidsPortefeuille_pct,Devise
[Fact_Positions]:
LOAD
    Date#(SnapshotDate, 'YYYY-MM-DD')    AS [Date Snapshot],
    Date#(SnapshotDate, 'YYYY-MM-DD')    AS [Date],
    PortefeuilleID,
    InstrumentID,
    Num#(Quantite)                       AS [Quantite Position],
    Num#(PrixRevientUnitaire)            AS [Prix Revient Unitaire],
    Num#(PrixMarcheUnitaire)             AS [Prix Marche Unitaire],
    Num#(ValeurAchat_EUR)                AS [Valeur Achat (EUR)],
    Num#(ValeurMarche_EUR)               AS [Valeur Marche (EUR)],
    Num#(PnL_EUR)                        AS [PnL (EUR)],
    Num#(PnL_pct)                        AS [PnL (%)],
    Num#(PoidsPortefeuille_pct)          AS [Poids Portefeuille (%)],
    Devise                               AS [Devise Position],
    If(Num#(PnL_EUR) >= 0, 'Positif', 'Negatif') AS [Signe PnL]
FROM [$(vDataPath)fact_positions.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── FACT_PERFORMANCES ────────────────────────────────────────
// CSV columns: PeriodeDate,PortefeuilleID,Rendement_pct,Benchmark_pct,
//              Alpha_pct,Volatilite_pct,RatioSharpe,MaxDrawdown_pct,
//              ValeurPortefeuille_EUR,FluxNets_EUR,RendementCumule_pct
// NOTE: NO InstrumentID in this table
[Fact_Performances]:
LOAD
    Date#(PeriodeDate, 'YYYY-MM-DD')     AS [Date Performance],
    Date#(PeriodeDate, 'YYYY-MM-DD')     AS [Date],
    PortefeuilleID,
    Num#(Rendement_pct)                  AS [Rendement (%)],
    Num#(Benchmark_pct)                  AS [Benchmark (%)],
    Num#(Alpha_pct)                      AS [Alpha (%)],
    Num#(Volatilite_pct)                 AS [Volatilite (%)],
    Num#(RatioSharpe)                    AS [Ratio Sharpe],
    Num#(MaxDrawdown_pct)                AS [Max Drawdown (%)],
    Num#(ValeurPortefeuille_EUR)         AS [Valeur Portefeuille (EUR)],
    Num#(FluxNets_EUR)                   AS [Flux Nets (EUR)],
    Num#(RendementCumule_pct)            AS [Rendement Cumule (%)],
    If(Num#(Alpha_pct) >= 0, 'Alpha Positif', 'Alpha Negatif') AS [Signe Alpha],
    If(Num#(Rendement_pct) >= Num#(Benchmark_pct),
       'Surperforme', 'Sous-performe')   AS [Vs Benchmark]
FROM [$(vDataPath)fact_performances.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── FACT_COURS_HISTORIQUES ───────────────────────────────────
// CSV columns: Date,InstrumentID,PrixOuverture,PrixHaut,PrixBas,
//              PrixCloture,Volume,Devise
// NOTE: NO PortefeuilleID in this table
[Fact_Cours]:
LOAD
    Date#(Date, 'YYYY-MM-DD')           AS [Date Cours],
    Date#(Date, 'YYYY-MM-DD')           AS [Date],
    InstrumentID,
    Num#(PrixOuverture)                 AS [Prix Ouverture],
    Num#(PrixHaut)                      AS [Prix Haut],
    Num#(PrixBas)                       AS [Prix Bas],
    Num#(PrixCloture)                   AS [Prix Cloture],
    Num#(Volume)                        AS [Volume],
    Devise                              AS [Devise Cours],
    Num#(PrixHaut) - Num#(PrixBas)      AS [Amplitude Journaliere]
FROM [$(vDataPath)fact_cours_historiques.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ── FACT_ALERTES_RISQUE ──────────────────────────────────────
// CSV columns: AlerteID,PortefeuilleID,ClientID,DateAlerte,TypeAlerte,
//              Severite,Statut,Description,ValeurMesure,SeuilAlerte,
//              DateResolution
// Severite values: Haute, Faible, Critique, Modérée
// Statut values:   En traitement, Ouverte, Ignorée, Résolue
[Fact_Alertes]:
LOAD
    AlerteID,
    PortefeuilleID,
    ClientID,
    Date#(DateAlerte, 'YYYY-MM-DD')     AS [Date Alerte],
    Date#(DateAlerte, 'YYYY-MM-DD')     AS [Date],
    TypeAlerte                          AS [Type Alerte],
    Severite,
    Statut                              AS [Statut Alerte],
    Description                         AS [Description Alerte],
    Num#(ValeurMesure)                  AS [Valeur Mesuree],
    Num#(SeuilAlerte)                   AS [Seuil Alerte],
    Date#(DateResolution, 'YYYY-MM-DD') AS [Date Resolution],
    If(Statut = 'Résolue',
       Date#(DateResolution, 'YYYY-MM-DD') - Date#(DateAlerte, 'YYYY-MM-DD'),
       Null())                          AS [Delai Resolution (jours)]
FROM [$(vDataPath)fact_alertes_risque.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ============================================================
// SECTION 3 : MAPPINGS & ENRICHMENTS
// ============================================================

// ── Macro-Classe mapping ─────────────────────────────────────
// Based on actual [Classe Actif] values in dim_instruments.csv:
// Actions, Taux, Immobilier, Monétaire, Matières Premières,
// Obligations HY, Obligations Convertibles, Private Equity, Épargne
Map_MacroClasse:
MAPPING LOAD * INLINE [
Classe Actif, Macro Classe Actif
Actions, Risque
Obligations HY, Risque
Private Equity, Risque
Taux, Defensif
Monétaire, Defensif
Épargne, Defensif
Immobilier, Diversifie
Matières Premières, Diversifie
Obligations Convertibles, Diversifie
];

// Enrich Dim_Instruments with Macro-Classe
[Dim_Instruments_Tmp]:
LOAD *,
    ApplyMap('Map_MacroClasse', [Classe Actif], 'Non classifie') AS [Macro Classe Actif]
Resident [Dim_Instruments];

Drop Table [Dim_Instruments];
RENAME Table [Dim_Instruments_Tmp] TO [Dim_Instruments];


// ============================================================
// SECTION 4 : MASTER CALENDAR
// ============================================================
// Builds a single [Date] field linking all fact tables.
// Uses Dim_Calendrier as the source (already contains full date range).
// All fact tables expose a [Date] field that links here.

[MasterCalendar]:
LOAD
    [Date],
    [Annee],
    [Mois],
    [Nom Mois],
    [Trimestre],
    [Semaine],
    [Annee-Mois],
    [Annee-Trimestre],
    [Semestre],
    [Type Jour],
    [Est Weekend],
    [Est Jour Ferie]
Resident [Dim_Calendrier];

Drop Table [Dim_Calendrier];

// ============================================================
// END OF SCRIPT
// ============================================================
exit script;
///$tab Section 2
// ============================================================
// QLIK SENSE - INVESTMENT TRACKING - SCRIPT DE CHARGEMENT
// Version : 1.0 | Date : 2025
// Architecture : Modele en etoile (Star Schema)
// ============================================================

// ── VARIABLES GLOBALES ────────────────────────────────────────
SET ThousandSep='.';
SET DecimalSep=',';
SET MoneyThousandSep='.';
SET MoneyDecimalSep=',';
SET MoneyFormat='# ##0,00 EUR;-# ##0,00 EUR';
SET TimeFormat='hh:mm:ss';
SET DateFormat='YYYY-MM-DD';
SET TimestampFormat='YYYY-MM-DD hh:mm:ss[.fff]';
SET FirstWeekDay=0;
SET BrokenWeeks=1;
SET ReferenceDay=4;
SET FirstMonthOfYear=1;
SET CollationLocale='fr-FR';
SET CreateSearchIndexOnReload=1;

LET vDataPath = 'lib://InvestmentData/';
LET vCurrentYear = Year(Today());
LET vCurrentMonth = Month(Today());
LET vReportDate = Date(Today(), 'YYYY-MM-DD');

// ============================================================
// SECTION 1 : DIMENSIONS (Tables de reference)
// ============================================================

// ── TABLE : DIM_CALENDRIER ────────────────────────────────────
[Dim_Calendrier]:
LOAD
    Date#(Date, 'YYYY-MM-DD')       AS [Date],
    Annee                            AS [Annee],
    Num#(Trimestre)                  AS [Trimestre],
    Num#(Mois)                       AS [Mois],
    NomMois                          AS [Nom Mois],
    Semaine                          AS [Semaine],
    JourSemaine                      AS [Jour Semaine],
    NomJour                          AS [Nom Jour],
    Num#(EstWeekend)                 AS [Est Weekend],
    AnneeMois                        AS [Annee-Mois],
    AnneeTrimestreTxt                AS [Annee-Trimestre],
    Semestre                         AS [Semestre],
    If(Num#(EstWeekend)=0, 'Jour Ouvre', 'Weekend') AS [Type Jour]
FROM [$(vDataPath)dim_calendrier.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);

// ── TABLE : DIM_CLIENTS ───────────────────────────────────────
[Dim_Clients]:
LOAD
    ClientID,
    Nom                              AS [Nom Client],
    Prenom                           AS [Prenom Client],
    Nom & ' ' & Prenom               AS [Nom Complet Client],
    Email                            AS [Email Client],
    Telephone                        AS [Telephone],
    Date#(DateNaissance, 'YYYY-MM-DD') AS [Date Naissance],
    Year(Today()) - Year(Date#(DateNaissance,'YYYY-MM-DD')) AS [Age Client],
    Segment                          AS [Segment Client],
    Pays                             AS [Pays Client],
    Ville                            AS [Ville Client],
    Date#(DateEntreeRelation, 'YYYY-MM-DD') AS [Date Entree Relation],
    Year(Today()) - Year(Date#(DateEntreeRelation,'YYYY-MM-DD')) AS [Anciennete (ans)],
    Conseiller                       AS ConseillerID,
    ProfilRisque                     AS [Profil Risque],
    StatutKYC                        AS [Statut KYC]
FROM [$(vDataPath)dim_clients.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);

// ── TABLE : DIM_INSTRUMENTS ───────────────────────────────────
[Dim_Instruments]:
LOAD
    InstrumentID,
    NomInstrument                    AS [Nom Instrument],
    TypeInstrument                   AS [Type Instrument],
    [Classe Actif]                   AS [Classe d'Actif],
    Devise                           AS [Devise Instrument],
    Pays                             AS [Pays Instrument],
    ISIN,
    Emetteur,
    NiveauRisque                     AS [Niveau Risque],
    Num#(FraisGestion_pct)           AS [Frais Gestion (%)]
FROM [$(vDataPath)dim_instruments.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);

// ── TABLE : DIM_CONSEILLERS ───────────────────────────────────
[Dim_Conseillers]:
LOAD
    ConseillerID,
    Nom                              AS [Nom Conseiller],
    Prenom                           AS [Prenom Conseiller],
    Nom & ' ' & Prenom               AS [Nom Complet Conseiller],
    Email                            AS [Email Conseiller],
    Bureau                           AS [Bureau],
    Equipe                           AS [Equipe],
    Num#(AnneeExperience)            AS [Annees Experience],
    Certification,
    Num#(NbClients)                  AS [Nb Clients],
    Num#(AuM_EUR)                    AS [AuM (EUR)]
FROM [$(vDataPath)dim_conseillers.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);

// ── TABLE : DIM_PORTEFEUILLES ─────────────────────────────────
[Dim_Portefeuilles]:
LOAD
    PortefeuilleID,
    ClientID,
    TypePortefeuille                 AS [Type Portefeuille],
    Date#(DateOuverture, 'YYYY-MM-DD') AS [Date Ouverture],
    Devise                           AS [Devise Portefeuille],
    Statut                           AS [Statut Portefeuille],
    ObjectifInvestissement           AS [Objectif Investissement],
    HorizonInvestissement            AS [Horizon Investissement],
    BenchmarkRef                     AS [Benchmark Reference]
FROM [$(vDataPath)dim_portefeuilles.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);


// ============================================================
// SECTION 2 : FAITS (Tables de faits)
// ============================================================

// ── TABLE : FACT_TRANSACTIONS ─────────────────────────────────
[Fact_Transactions]:
LOAD
    TransactionID,
    PortefeuilleID,
    InstrumentID,
    Date#(DateTransaction, 'YYYY-MM-DD') AS [Date Transaction],
    Date#(DateTransaction, 'YYYY-MM-DD') AS [Date],
    TypeTransaction                   AS [Type Transaction],
    Num#(Quantite)                    AS [Quantite],
    Num#(PrixUnitaire)                AS [Prix Unitaire (EUR)],
    Num#(MontantBrut)                 AS [Montant Brut (EUR)],
    Num#(Frais)                       AS [Frais (EUR)],
    Num#(MontantNet)                  AS [Montant Net],
    Devise                            AS [Devise Transaction],
    Num#(TauxChange_EUR)              AS [Taux Change EUR],
    Num#(MontantNet_EUR)              AS [Montant Net EUR],
    Statut                            AS [Statut Transaction],
    Courtier,
    Operateur,
    If(TypeTransaction='Achat',    Num#(MontantNet_EUR), 0) AS [Montant Achat EUR],
    If(TypeTransaction='Vente',    Num#(MontantNet_EUR), 0) AS [Montant Vente EUR],
    If(TypeTransaction='Dividende',Num#(MontantNet_EUR), 0) AS [Dividendes EUR],
    If(TypeTransaction='Frais',    Num#(MontantNet_EUR), 0) AS [Total Frais EUR]
FROM [$(vDataPath)fact_transactions.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq)
WHERE Statut = 'Execute';

// ── TABLE : FACT_POSITIONS ────────────────────────────────────
[Fact_Positions]:
LOAD
    Date#(SnapshotDate, 'YYYY-MM-DD') AS [Date Snapshot],
    Date#(SnapshotDate, 'YYYY-MM-DD') AS [Date],
    PortefeuilleID,
    InstrumentID,
    Num#(Quantite)                    AS [Quantite Position],
    Num#(PrixRevientUnitaire)         AS [Prix Revient Unitaire],
    Num#(PrixMarcheUnitaire)          AS [Prix Marche Unitaire],
    Num#(ValeurAchat_EUR)             AS [Valeur Achat (EUR)],
    Num#(ValeurMarche_EUR)            AS [Valeur Marche (EUR)],
    Num#(PnL_EUR)                     AS [PnL (EUR)],
    Num#(PnL_pct)                     AS [PnL (%)],
    Num#(PoidsPortefeuille_pct)       AS [Poids Portefeuille (%)],
    If(Num#(PnL_EUR) >= 0, 'Positif', 'Negatif') AS [Signe PnL]
FROM [$(vDataPath)fact_positions.csv]
(txt, codepage is 28591, embedded labels, delimiter is ',', msq);

// ── TABLE : FACT_PERFORMANCES ─────────────────────────────────
[Fact_Performances]:
LOAD
    Date#(PeriodeDate, 'YYYY-MM-DD')  AS [Date Performance],
    Date#(PeriodeDate, 'YYYY-MM-DD')  AS [Date],
    PortefeuilleID,
    Num#(Rendement_pct)               AS [Rendement (%)],
    Num#(Benchmark_pct)               AS [Benchmark (%)],
    Num#(Alpha_pct)                   AS [Alpha (%)],
    Num#(Volatilite_pct)              AS [Volatilite (%)],
    Num#(RatioSharpe)                 AS [Ratio Sharpe],
    Num#(MaxDrawdown_pct)             AS [Max Drawdown (%)],
    Num#(ValeurPortefeuille_EUR)      AS [Valeur Portefeuille (EUR)],
    Num#(FluxNets_EUR)                AS [Flux Nets (EUR)],
    Num#(RendementCumule_pct)         AS [Rendement Cumule (%)],
