LOAD DISTINCT [Date Snapshot] AS TmpDate
Resident [Fact_Positions];

CONCATENATE([TempDates])
LOAD DISTINCT [Date Performance] AS TmpDate
Resident [Fact_Performances];

CONCATENATE([TempDates])
LOAD DISTINCT [Date Alerte] AS TmpDate
Resident [Fact_Alertes];

